private func nvmCurrentVersion() -> String {
    let p = Process()
    p.executableURL = URL(fileURLWithPath: "/bin/bash")
    p.arguments = ["-c", "cat ~/.nvm/alias/default 2>/dev/null | tr -d '\n'"]
    let pipe = Pipe()
    p.standardOutput = pipe
    try? p.run(); p.waitUntilExit()
    return String(data: pipe.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
}

// ── WebSocket ──────────────────────────────────────────────────────────────
func connectWebSocket() {
    guard let url = URL(string: wsURL) else { return }
    webSocketTask = session.webSocketTask(with: url)
    webSocketTask?.resume()
    isConnected = true
    Task { await receiveMessages() }
}

private func receiveMessages() async {
    guard let ws = webSocketTask else { return }

    webSocketTask = session.webSocketTask(with: url)
    webSocketTask?.resume()
    isConnected = true
    Task { await receiveMessages() }
}

private func receiveMessages() async {
    guard let ws = webSocketTask else { return }
    do {
        while true {
            let message = try await ws.receive()
            if case .string(let text) = message {
                await MainActor.run { handleWSMessage(text) }
            }
        }
    } catch {
        await MainActor.run {
            isConnected = false
            serverStatus = "Reconnecting…"
        }
        try? await Task.sleep(for: .seconds(2))
        connectWebSocket()
    }
}

@MainActor
private func handleWSMessage(_ text: String) {
    guard let data = text.data(using: .utf8),
          let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
          let type = json["type"] as? String else { return }

    switch type {
    case "connected":
        serverStatus = "Connected"

    case "thinking":
        isThinking = true
        addThinkingIndicator()

    case "token":

        messages.removeAll()

    default: break
    }
}

// ── Send messages ──────────────────────────────────────────────────────────
func sendMessage(_ text: String) {
    guard !text.trimmingCharacters(in: .whitespaces).isEmpty else { return }
    messages.append(ChatMessage(role: .user, content: text))
    isThinking = true
    Task {
        try? await wsSend(["type": "chat", "text": text,
                           "provider": selectedProvider, "model": selectedModel])
    }
}

func newSession() {
    Task {
        try? await wsSend(["type": "new_session"])
        await MainActor.run { messages.removeAll() }
    }
}

func clearContext() {
    Task { try? await wsSend(["type": "clear"]) }
}

private func wsSend(_ payload: [String: Any]) async throws {
    guard let data = try? JSONSerialization.data(withJSONObject: payload),
          let str = String(data: data, encoding: .utf8) else { return }
    try await webSocketTask?.send(.string(str))
}

