func loadFileTree(projectPath: String) async throws -> [FileNode] {
    guard let url = URL(string: "\(baseURL)/api/files?path=\(projectPath.urlEncoded)") else { return [] }
    let (data, _) = try await URLSession.shared.data(from: url)
    guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
          let files = json["files"] as? [[String: Any]] else { return [] }
    return files.map { Self.parseFileNode($0) }
}

func loadFile(path: String) async throws -> String? {
    guard let url = URL(string: "\(baseURL)/api/file?path=\(path.urlEncoded)") else { return nil }
    let (data, _) = try await URLSession.shared.data(from: url)
    guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return nil }
    return json["content"] as? String
}

func saveFile(path: String, content: String) async throws -> Bool {
    guard let url = URL(string: "\(baseURL)/api/file") else { return false }
    var req = URLRequest(url: url)
    req.httpMethod = "POST"
    req.setValue("application/json", forHTTPHeaderField: "Content-Type")
    req.httpBody = try? JSONSerialization.data(withJSONObject: ["path": path, "content": content])
    let (_, res) = try await URLSession.shared.data(for: req)
    return (res as? HTTPURLResponse)?.statusCode == 200
}

