        if let j = messages[i].toolCalls.indices.last(where: { messages[i].toolCalls[$0].name == name && !messages[i].toolCalls[$0].done }) {
            messages[i].toolCalls[j].result = result
            messages[i].toolCalls[j].done = true
            return
        }
    }

