// ── Message bubbles ───────────────────────────────────────────────────────────
struct MessageBubble: View {
    let message: ChatMessage
    @State private var isCopied = false

    var body: some View {
        VStack(alignment: .leading, spacing: 4) {
            // Role label
            HStack {
                Text(roleLabel)
                    .font(.system(size: 10, weight: .semibold))
                    .foregroundColor(roleColor)
                    .tracking(0.5)
                Spacer()
                Button(action: copyContent) {
                    Image(systemName: isCopied ? "checkmark" : "doc.on.doc")
                        .font(.system(size: 10))
                        .foregroundColor(.appTextDim)
                }
                .buttonStyle(.plain)
                .opacity(0.6)
            }

            // Content
            Text(message.content)
                .font(.system(size: 13))
                .foregroundColor(.appText)
                .textSelection(.enabled)
                .padding(10)
                .background(bubbleBg)
                .cornerRadius(8)
                .overlay(RoundedRectangle(cornerRadius: 8).stroke(bubbleBorder, lineWidth: 1))

            // Tool calls
            ForEach(message.toolCalls) { tool in
                ToolCallView(tool: tool)
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)

            .overlay(RoundedRectangle(cornerRadius: 8).stroke(bubbleBorder, lineWidth: 1))

        // Tool calls
        ForEach(message.toolCalls) { tool in
            ToolCallView(tool: tool)
        }
    }
    .frame(maxWidth: .infinity, alignment: .leading)
}

var roleLabel: String {
    switch message.role {
    case .user:  return "YOU"
    case .agent: return "DEVLAB"
    case .tool:  return "TOOL"
    case .error: return "ERROR"
    }
}

var roleColor: Color {
    switch message.role {
    case .user:  return .appAccent
    case .agent: return .green
    case .tool:  return .yellow
    case .error: return .red
    }
}

var bubbleBg: Color {
    switch message.role {
    case .user:  return Color.appSurface2
    case .error: return Color.red.opacity(0.1)
    default:     return Color.appSurface
    }
}

var bubbleBorder: Color {
    switch message.role {
    case .user:  return Color.appAccent.opacity(0.4)
    case .error: return Color.red.opacity(0.5)

        default:     return Color.appSurface
        }
    }

    var bubbleBorder: Color {
        switch message.role {
        case .user:  return Color.appAccent.opacity(0.4)
        case .error: return Color.red.opacity(0.5)
        default:     return Color.appBorder
        }
    }

    func copyContent() {
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(message.content, forType: .string)
        isCopied = true
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) { isCopied = false }
    }
}

