public void StartServer(string agentRoot)
{
    ServerStatus = "Starting agent server…";

    var nodePath = FindNode();
    if (nodePath == null) { ServerStatus = "Node.js not found. Install from nodejs.org"; return; }

    var process = new Process
    {
        StartInfo = new ProcessStartInfo
        {
            FileName = nodePath,
            Arguments = $"index.js ui \"{agentRoot}\" --no-open",
            WorkingDirectory = agentRoot,
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            CreateNoWindow = true,
            Environment = { ["UI_PORT"] = Port.ToString() }
        }
    };

    bool started = false;

            RedirectStandardOutput = true,
            RedirectStandardError = true,
            CreateNoWindow = true,
            Environment = { ["UI_PORT"] = Port.ToString() }
        }
    };

    bool started = false;
    process.OutputDataReceived += (_, e) =>
    {
        if (started || e.Data == null) return;
        if (e.Data.Contains("running at") || e.Data.Contains("localhost:"))
        {
            started = true;
            App.Current.Dispatcher.Invoke(() =>
            {
                ServerStatus = "Server ready";
                _ = ConnectWebSocketAsync();
                _ = LoadProvidersAsync();
            });
        }
    };

    process.Start();
    process.BeginOutputReadLine();
    process.BeginErrorReadLine();
    _serverProcess = process;
}

