{
    while (!_cts.IsCancellationRequested)
    {
        try
        {
            _ws = new ClientWebSocket();
            await _ws.ConnectAsync(new Uri(WsUrl), _cts.Token);
            IsConnected = true;
            _ = ReceiveLoopAsync();
            return;
        }
        catch
        {
            IsConnected = false;
            await Task.Delay(2000, _cts.Token);
        }
    }
}

