private void RenderTabs()
{
    TabBar.Children.Clear();
    foreach (var f in _openFiles)
    {
        var border = new Border
        {
            BorderBrush = new SolidColorBrush(Color.FromRgb(0x2E, 0x2E, 0x2E)),
