  let out = text;
  let count = 0;
  for (const p of SECRET_PATTERNS) {
    out = out.replace(p.re, (...m) => {
      count++;
      return p.keepPrefix ? `${m[1]}[REDACTED:${p.label}]` : `[REDACTED:${p.label}]`;
    });
  }
  return count > 0 ? out : text;
}

