  }

  return {
    projectPath,
    filesScanned,
    totalFindings: allFindings.length,
    criticals: allFindings.filter(f => f.severity === 'CRITICAL').length,
    highs: allFindings.filter(f => f.severity === 'HIGH').length,
    byFile,
  };
}

