RUN mvn dependency:go-offline -q
COPY src ./src
RUN mvn package -q -DskipTests

FROM eclipse-temurin:21-jre-alpine
COPY --from=build /src/target/*.jar /app.jar
EXPOSE ${a.port}
CMD ["java", "-jar", "/app.jar"]
`,
};
DOCKERFILES.nextjs = DOCKERFILES.node;
DOCKERFILES['node-server'] = DOCKERFILES.node;
DOCKERFILES.django = DOCKERFILES.python;
DOCKERFILES['java-gradle'] = DOCKERFILES['java-maven'];

export function generateDockerfile({ path: dir = '.', write = true, compose = false } = {}) {
  const root = path.resolve(dir);
  if (!fs.existsSync(root)) return { error: `Path not found: ${root}` };
  const app = detectAppType(root);
  const template = DOCKERFILES[app.type];
  if (!template) return { error: `Unsupported project type '${app.type}' — supported: node, nextjs, python, django, go, java (maven/gradle)` };

  const dockerfile = template(app);
  const dockerignore = ['node_modules', '.git', '.env*', '*.log', 'dist', 'build', '__pycache__', '.devlab', 'coverage'].join('\n') + '\n';
  const name = path.basename(root).toLowerCase().replace(/[^a-z0-9-]/g, '-');
  const composeYml = `services:
  ${name}:
    build: .
    ports:
      - "${app.port}:${app.port}"
    environment:
      - NODE_ENV=production

  const name = path.basename(root).toLowerCase().replace(/[^a-z0-9-]/g, '-');
  const composeYml = `services:
  ${name}:
    build: .
    ports:
      - "${app.port}:${app.port}"
    environment:
      - NODE_ENV=production
    restart: unless-stopped
`;

  const written = [];
  if (write) {
    const df = path.join(root, 'Dockerfile');
    if (fs.existsSync(df)) return { error: 'Dockerfile already exists — delete it first or use write:false to preview', preview: dockerfile };
    fs.writeFileSync(df, dockerfile); written.push(df);
    const di = path.join(root, '.dockerignore');
    if (!fs.existsSync(di)) { fs.writeFileSync(di, dockerignore); written.push(di); }
    if (compose) {
      const cf = path.join(root, 'docker-compose.yml');
      if (!fs.existsSync(cf)) { fs.writeFileSync(cf, composeYml); written.push(cf); }
    }
  }
  return {
    detected: app.type,
    port: app.port,
    written,
    ...(write ? {} : { dockerfile, dockerignore, ...(compose ? { compose: composeYml } : {}) }),
    next: `docker build -t ${name}:latest ${dir} && docker run --rm -p ${app.port}:${app.port} ${name}:latest`,
  };
}

// src/tools/files.js — file system operations
import { readFileSync, writeFileSync, existsSync, statSync, mkdirSync, unlinkSync, readdirSync } from 'fs';
import { resolve, relative, extname, basename, dirname, join } from 'path';
import { glob } from 'glob';
import { MAX_FILE_SIZE } from '../config.js';
import { isProtectedPath } from '../security.js';

const TEXT_EXTS = new Set([
  '.js','.ts','.jsx','.tsx','.mjs','.cjs',
  '.py','.rb','.go','.rs','.java','.kt','.swift','.c','.cpp','.h','.cs',
  '.html','.css','.scss','.less','.svelte','.vue',
  '.json','.yaml','.yml','.toml','.xml','.env','.ini','.conf',
  '.md','.txt','.sh','.bash','.zsh','.fish',
  '.sql','.graphql','.gql','.proto',
  '.dockerfile','dockerfile','.gitignore','.npmrc',
]);

function isTextFile(filePath) {
  const ext = extname(filePath).toLowerCase();
  const base = basename(filePath).toLowerCase();
  return TEXT_EXTS.has(ext) || TEXT_EXTS.has(base);
}

export function readFile(path) {
  const absPath = resolve(path);
  if (isProtectedPath(absPath)) return { error: `Access denied: ${path} is a protected credentials file.` };
  if (!existsSync(absPath)) return { error: `File not found: ${path}` };
  const stat = statSync(absPath);
  if (stat.size > MAX_FILE_SIZE) return { error: `File too large (${Math.round(stat.size/1024)}KB). Use search_files to find specific sections.` };
  if (!isTextFile(absPath)) return { error: `Binary file skipped: ${path}` };
  try {
    const content = readFileSync(absPath, 'utf8');
    const lines = content.split('\n').length;
    return { path: absPath, content, lines, size: stat.size };
  } catch (e) {
    return { error: e.message };
  }
}

export function writeFile(path, content, { createDirs = true } = {}) {

    const lines = content.split('\n').length;
    return { path: absPath, content, lines, size: stat.size };
  } catch (e) {
    return { error: e.message };
  }
}

export function writeFile(path, content, { createDirs = true } = {}) {
  const absPath = resolve(path);
  if (isProtectedPath(absPath)) return { error: `Access denied: ${path} is a protected credentials file.` };
  try {
    if (createDirs) mkdirSync(dirname(absPath), { recursive: true });
    writeFileSync(absPath, content, 'utf8');
    const lines = content.split('\n').length;
    return { path: absPath, written: true, lines, bytes: Buffer.byteLength(content) };
  } catch (e) {
    return { error: e.message };
  }
}

export function deleteFile(path) {
  const absPath = resolve(path);
  if (isProtectedPath(absPath)) return { error: `Access denied: ${path} is a protected credentials file.` };
  if (!existsSync(absPath)) return { error: `File not found: ${path}` };
  try {
    unlinkSync(absPath);
    return { deleted: absPath };
  } catch (e) {
    return { error: e.message };
  }
}

