  }

  // Check function length
  const funcRe = /(?:function\s+\w+|def\s+\w+|func\s+\w+|\w+\s*=\s*(?:async\s*)?\([^)]*\)\s*=>|void\s+\w+\s*\()\s*\{?/g;
