}

function canonicalPath(pathValue) {
  return normalizeContractPath(pathValue)
    .replace(/:([^/]+)/g, ':param')
    .replace(/\/+/g, '/');
}

function parsePathSegments(pathValue) {
  return canonicalPath(pathValue).split('/').filter(Boolean);
