    lines.push('\n' + chalk.bold.magenta('🔎 API contract suggestions:'));
    for (const s of review.apiContractSuggestions) lines.push(chalk.magenta(`  • ${s}`));
  }

  lines.push('');
  return lines.join('\n');
}

