function getPRChanges(dir, base) {
  try {
    const range = base ? `${base}...HEAD` : 'HEAD~1..HEAD';
    const stat = execSync(`git --no-pager diff --stat ${range}`, { cwd: dir, encoding: 'utf8', timeout: 15000, stdio: ['ignore', 'pipe', 'ignore'] });
